import json
import re
import pandas as pd

def task_func(json_str):
    if not json_str:
        return pd.DataFrame()

    try:
        data = json.loads(json_str)
    except (json.JSONDecodeError, TypeError):
        return pd.DataFrame()

    if not isinstance(data, dict):
        return pd.DataFrame()

    def double_numeric(v):
        if isinstance(v, (int, float)):
            return float(v) * 2
        if isinstance(v, str):
            if re.match(r'^-?\d+(\.\d+)?$', v):
                return float(v) * 2
            return v
        if isinstance(v, list):
            return [double_numeric(item) for item in v]
        return v

    normalized_data = {k: double_numeric(v) for k, v in data.items()}

    try:
        df = pd.DataFrame(normalized_data)
        return df
    except Exception:
        return pd.DataFrame()
